@startuml

class Location {
  + address : string
}

class Driver {
  + firstName : string
  + lastName : string
}

class Vehicle {
  + vehicleNumber : string
}

class Truck extends Vehicle {
  + weight : float
}

class Car extends Vehicle {
  + seats : int
}

class Van extends Vehicle {}

class Order {
  + origin : string
  + destination : string
  + executionDate : date
}

Location "1" *-- "0..*" Driver
Location "1" *-- "0..*" Vehicle
Location "1" -- "1..*" Order : origin
Location "1" -- "1..*" Order : destination
Driver "1" -- "0..1" Order : carries out
Driver "1" -- "0..1" Vehicle : drives
Order "*" -- "1..*" Driver : assigned to

@enduml

